<?php if (!defined('ABSPATH')) exit; get_header(); ?><main><?php smt_breadcrumbs(); ?><?php while(have_posts()):the_post(); ?><article class="single-article"><header class="ui-page-hero"><div class="container"><span class="eyebrow"><?php echo esc_html(get_the_date()); ?></span><h1><?php the_title(); ?></h1><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),35)); ?></p></div></header><div class="container article-content"><?php if(has_post_thumbnail()) the_post_thumbnail('large',['class'=>'article-featured']); the_content(); wp_link_pages(); ?></div></article><?php endwhile; ?></main><?php get_footer(); ?>